"Backpack","desc":"Perfect Creeping Death — Applying a status effect also applies it to all enemies within 10m of your target. Cooldown: 10s."}]},{"n":"Lengmo","t":"brand","focus":"hybrid","pieces":[{"p":"1pc","b":"+20% Explosive Resistance"},{"p":"2pc","b":"+20% Skill Health"},{"p":"3pc","b":"+30% LMG Damage"}],"roll":"Critical Hit Chance (DPS lean) or Skill Haste (skill lean)","named":[{"name":"Backbone","slot":"Chest","desc":"Perfectly Unstoppable Force — Killing an enemy increases total weapon damage by 7% for 15s. Stacks up to 5. Grenade kills add 2 stacks."}]},{"n":"Ceska Vyroba","t":"brand","focus":"hybrid","pieces":[{"p":"1pc","b":"+8% Critical Hit Chance"},{"p":"2pc","b":"+20% Hazard Protection"},{"p":"3pc","b":"+90% Health"}],"roll":"Critical Hit Damage if DPS lean; Armor Regeneration if tank lean","named":[{"name":"Devil's Due","slot":"Knees","desc":"Perfect Clutch — Below 20% armor: crits repair 2.5% of missing armor. On kill: crits repair 2.5% of missing armor for 4s (each red core adds 1s, max 10s)."}]},{"n":"Douglas & Harding","t":"brand","focus":"dps","pieces":[{"p":"1pc","b":"+20% Pistol Damage"},{"p":"2pc","b":"+30% Weapon Stability"},{"p":"3pc","b":"+50% Weapon Accuracy"}],"roll":"Critical Hit Chance + Critical Hit Damage","named":[{"name":"Punch Drunk","slot":"Mask","desc":"Extra Headshot Damage bonus."}]},{"n":"Grupo Sombra","t":"brand","focus":"dps","pieces":[{"p":"1pc","b":"+13% Critical Hit Damage"},{"p":"2pc","b":"+20% Explosives Damage"},{"p":"3pc","b":"+13% Headshot Damage"}],"roll":"Critical Hit Chance — pairs directly with the set's own Crit Damage bonus","named":[]},{"n":"Airaldi","t":"brand","focus":"dps","pieces":[{"p":"1pc","b":"+10% Marksman Rifle Damage"},{"p":"2pc","b":"+13% Headshot Damage"},{"p":"3pc","b":"+5% Damage to Armor"}],"roll":"Critical Hit Chance","named":[]},{"n":"Sokolov","t":"brand","focus":"dps","pieces":[{"p":"1pc","b":"+10% SMG Damage"},{"p":"2pc","b":"+13% Critical Hit Damage"},{"p":"3pc","b":"+8% Critical Hit Chance"}],"roll":"Already covers the crit pair — fill remaining slots with more Crit Chance/Damage","named":[]},{"n":"Zwiadowka","t":"brand","focus":"dps","pieces":[{"p":"1pc","b":"+15% Mag Size"},{"p":"2pc","b":"+20% Rifle Damage"},{"p":"3pc","b":"+30% Weapon Handling"}],"roll":"Headshot Damage + Critical Hit Chance","named":[]},{"n":"Legatus","t":"brand","focus":"dps","pieces":[{"p":"1pc","b":"+30% Swap Speed"},{"p":"2pc","b":"+70% Optimal Range"},{"p":"3pc","b":"+15% Weapon Damage"}],"roll":"Critical Hit Chance + Critical Hit Damage","named":[{"name":"Vigil","slot":"Chest","desc":"Perfect Versatile — Amplifies total weapon damage for 10s when swapping between different primary/secondary weapon types (45% to close/long range class, 20% to mid). Max once per 5s per weapon type."}]},{"n":"Shiny Monkey Gear","t":"brand","focus":"heal","pieces":[{"p":"1pc","b":"+15% Skill Duration"},{"p":"2pc","b":"+5% Skill Efficiency"},{"p":"3pc","b":"+52% Repair Skills"}],"roll":"Skill Health","named":[{"name":"Axel","slot":"Chest","desc":"Perfect Energize — Using an armor kit grants +1 Skill Tier for 15s. If at Skill Tier 6, grants Overcharge. Cooldown: 30s."}]},{"n":"Imminence Armaments","t":"brand","focus":"dps","pieces":[{"p":"1pc","b":"+5% Weapon Damage"},{"p":"2pc","b":"+100% Increased Threat"},{"p":"3pc","b":"+60% Pistol Damage"}],"roll":"Critical Hit Chance + Critical Hit Damage","named":[{"name":"Cap'n","slot":"Chest","desc":"Perfect Leadership — Cover-to-cover movement grants 20% of your armor as bonus armor to you and all allies for 10s (tripled if ending within 10m of an enemy). Cooldown: 10s."}]},{"n":"Urban Lookout","t":"brand","focus":"hybrid","pieces":[{"p":"1pc","b":"+10% Accuracy"},{"p":"2pc","b":"+30% Skill Duration"},{"p":"3pc","b":"+30% MMR Damage"}],"roll":"Critical Hit Chance (DPS lean) or Skill Haste (skill lean)","named":[]},{"n":"Unit Alloys","t":"brand","focus":"dps","pieces":[{"p":"1pc","b":"+5% Rate of Fire"},{"p":"2pc","b":"+20% Assault Rifle Damage"},{"p":"3pc","b":"+50% Magazine Size"}],"roll":"Critical Hit Chance + Critical Hit Damage","named":[]},{"n":"Royal Works","t":"brand","focus":"dps","pieces":[{"p":"1pc","b":"+5% Weapon Handling"},{"p":"2pc","b":"+32.5% Magazine Size"},{"p":"3pc","b":"+15% Crit Damage"}],"roll":"Critical Hit Chance — pairs directly with the set's own Crit Damage bonus","named":[{"name":"Bulldog","slot":"Chest","desc":"Perfect Composure — While in cover, increases total weapon damage by 20%."}]},{"n":"Edelweiss GPz","t":"brand","focus":"heal","pieces":[{"p":"1pc","b":"+18% Repair Skills"},{"p":"2pc","b":"+20% Skill Haste"},{"p":"3pc","b":"+8% Skill Efficiency"}],"roll":"Skill Health","named":[{"name":"Momma Badger","slot":"Chest","desc":"Perfect Safeguard — While at full armor, increases total skill repair by 160%."}]}]$seed$::jsonb, true, 'seed')
