iversal"},{"n":"Preservation","v":"sit","d":"Any weapon. Kills repair 10% armour over 5s; headshot kills repair an extra 10%.","w":"Handy survivability while you're gearing solo — usually dropped at full endgame DPS.","scope":"universal"},{"n":"Future Perfect","v":"sit","d":"Any weapon. Weapon kills grant +1 skill tier for 15s (stacks to 3); kills at tier 6 grant Overcharge.","w":"Strong on skill-tier builds — irrelevant to weapon-damage builds.","scope":"universal"},{"n":"Sledgehammer","v":"sit","d":"Any weapon. Grenade damage marks targets; marked enemies take +30% armour damage and move slower.","w":"Niche armour-shred utility. Not a general DPS pick.","scope":"universal"},{"n":"Steady Handed","v":"sit","d":"Any weapon. Hits stack +1% accuracy & stability; at 100 stacks consumes them to refill the mag.","w":"Light utility, mostly for hard-to-control weapons. Not a damage pick.","scope":"universal"},{"n":"Close & Personal","v":"sit","d":"All weapons. Killing a target within 7m grants +30% weapon damage for 10s.","w":"Risky at high difficulty; aggressive close-range only.","scope":"universal"},{"n":"Near Sighted","v":"skip","d":"Assault Rifles. +80% stability at the cost of -35% optimal range.","w":"Pure handling trade — no damage. Skip for DPS.","scope":"class"},{"n":"On Empty","v":"skip","d":"Assault Rifles. Reloading from empty grants +30% weapon handling for 10s.","w":"Marginal quality-of-life. Not worth a slot.","scope":"class"}]},{"id":"SMG","name":"SMG","tag":"Close range · high rate of fire","attrs":[{"name":"Critical Hit Chance","note":"Fast RPM means crit procs (Killer, Strained) land constantly."},{"name":"Critical Hit Damage","note":"Pairs with the chance above for burst close-range damage."},{"name":"Weapon Handling","note":"Faster ADS and recoil recovery matter more up close than at range."}],"talents":[{"n":"Measured","v":"keep","d":"AR / SMG / LMG. Top half of the mag = higher RPM; bottom half = +30% total weapon damage.","w":"Strong sustained DPS, 