values ('hunter-fury-gaming-brigade', 'dps', 'published', 50, $seed${"id":"hunter-fury-gaming-brigade","cat":"dps","name":"Hunter Fury - Gaming Brigade","subtitle":"In their face killer","diff":"easy","spec":"Gunner","slots":[{"slot":"MASK","set":"Hunter's Fury","logo":"hunters"},{"slot":"CHEST","set":"Sokolov Concern","logo":"sokolov","talent":"Intimidate"},{"slot":"BACKPACK","set":"Memento","logo":"memento","talent":"Kill Confirmed","exotic":true},{"slot":"GLOVES","set":"Hunter's Fury","logo":"hunters"},{"slot":"HOLSTER","set":"Hunter's Fury","logo":"hunters"},{"slot":"KNEEPADS","set":"Hunter's Fury","logo":"hunters"}],"statsLeft":[{"l":"Weapons","v":"SMG\nAR"},{"l":"Skills","v":"Pulse\nDefender Drone"},{"l":"Exotic","v":"Lady Death"}],"statsRight":[{"l":"Cores","v":"3 * Red 3 * Blue"}],"playstyle":"Up close and melt everything."}$seed$::jsonb, 'seed')
